import { planIntroMonthlyCents } from "@/lib/intro-pricing";

/**
 * The single live source of truth for "our cheapest VPS starts at $X/mo" copy
 * scattered across the use-case marketing pages (docker-hosting, vpn-server-hosting,
 * nodejs-hosting, n8n-hosting, discord-bot-hosting, nextcloud-hosting,
 * cheap-vps-hosting, affordable-vps-hosting, best-value-vps, wordpress-vps-hosting,
 * free-vps, singapore-vps-hosting, ...).
 *
 * These pages used to hard-code a literal "$6.49" / plan name "Nano" directly into
 * prose (title/sub/why/steps/FAQ) — a snapshot of a plan that has since been renamed
 * ("Starter") and repriced. A hardcoded number like that silently drifts from the
 * real catalog forever. This helper reads the SAME live `db.plan` rows the page
 * already fetches for its <PricingGrid/>, so the headline figure quoted in prose is
 * guaranteed to match what the pricing grid below it actually shows.
 *
 * `fromLabel` is the LOWEST real price — the intro/first-term rate when the
 * cheapest plan has one configured (`planIntroMonthlyCents`), else its regular
 * price. `renewsLabel` is non-null only when an intro applies, so callers can
 * fold in the same "renews at $Y/mo" disclosure the deploy wizard and the
 * PricingExplorer/PricingGrid cards use — never a bare low number with the
 * renewal hidden.
 */
export type CheapestVpsPricing = {
  /** Real plan name, e.g. "Starter" (NOT a hardcoded "Nano" that no longer exists). */
  planName: string;
  /** e.g. "$8.88" — the lowest real price: intro rate if one is set, else regular. */
  fromLabel: string;
  /** e.g. "$15.98" — the regular/renewal price. Null when there's no intro (fromLabel === the regular price already, nothing to disclose). */
  renewsLabel: string | null;
};

function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

export function cheapestVpsPricing(
  plans: { name: string; priceCents: number }[],
): CheapestVpsPricing | null {
  if (!plans.length) return null;
  const cheapest = plans.reduce((a, b) => (a.priceCents <= b.priceCents ? a : b));
  const introCents = planIntroMonthlyCents(cheapest);
  const fromCents = introCents ?? cheapest.priceCents;
  return {
    planName: cheapest.name,
    fromLabel: money(fromCents),
    renewsLabel: introCents != null ? money(cheapest.priceCents) : null,
  };
}

