  // object directly, so this page's "from $X/mo" copy stays intro-aware.
  return {
    id: p.id,
    name: "",
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: 1,
    priceCents: p.priceCents,
    storageTier: "nvme",
    ...({ introPriceCents: p.introPriceCents, introTermMonths: p.introTermMonths } as object),
  } as LandingPlan;
}

